// Empty shells of the image view and its cache module, compiled when the image module
// is out of the build (off in the app's `isoform.config.json`).
//
// The app generated by React Native looks the lib's components and modules up with
// `NSClassFromString` inside a dictionary: a missing class crashes the app on launch.
// These shells keep the names; JS never renders the view with the module off, and the
// module resolves `false` (nothing prefetched).

#import <React/RCTViewComponentView.h>
#import <IsoformSpec/IsoformSpec.h>

#import <react/renderer/components/IsoformSpec/ComponentDescriptors.h>

#import "RCTFabricComponentsPlugins.h"

using namespace facebook::react;

@interface IsoImageView : RCTViewComponentView
@end

@implementation IsoImageView

+ (ComponentDescriptorProvider)componentDescriptorProvider
{
  return concreteComponentDescriptorProvider<IsoImageViewComponentDescriptor>();
}

@end

Class<RCTComponentViewProtocol> IsoImageViewCls(void)
{
  return IsoImageView.class;
}

@interface IsoImageModule : NSObject <NativeIsoImageModuleSpec>
@end

@implementation IsoImageModule

RCT_EXPORT_MODULE()

- (void)prefetch:(NSArray *)urls
         headers:(NSArray *)headers
          memory:(BOOL)memory
            disk:(BOOL)disk
         resolve:(RCTPromiseResolveBlock)resolve
          reject:(RCTPromiseRejectBlock)reject
{
  resolve(@NO);
}

- (void)clear:(BOOL)memory disk:(BOOL)disk resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  resolve(nil);
}

- (std::shared_ptr<facebook::react::TurboModule>)getTurboModule:(const facebook::react::ObjCTurboModule::InitParams &)params
{
  return std::make_shared<facebook::react::NativeIsoImageModuleSpecJSI>(params);
}

@end
